$function getImgList(){
  var num;
  if (html.indexOf("<html style")!=-1) {
    num =  java.getString("class.bottomCode.-1@tag.span@text",false);
  } else {
    var a = html.match(/2=\[(.*?)\]/)[1].split(",");
    num = a.length.toString();
  }
  var cid = html.match(/CHAPTER_ID = (\d+)/)[1];
  var piclist = new Array();
  var temp, ges, pix;
  for (var i=0; i<num; i++) {
    temp = java.aJax("http://www.manben.com/imageshow.ashx?&cid="+cid+"&page="+(i+1)+"&showtype=2&ispre=0");
    ges = temp.match(/"Images":"(.*?)"/)[1];
    pix = temp.match(/"ImagePix":"(.*?)"/)[1];
    piclist.push(pix+ges);
  }
  return piclist;
}

