$function getImgList() {
  var str = html.match(/var chapterImages = \[(.*?)\];var chapterPath = "(.*?)";/);
  eval(str[0]);
  var host = "https://res.xiaoqinre.com/";
  var piclist = new Array([chapterImages.length]);
  for (var i = 0; i < chapterImages.length; i++) {
    if (chapterImages[i].search(/^(http:|https:)/) == 0) {
      piclist[i] = chapterImages[i];
    } else {
      piclist[i] = host + chapterPath.replace(/(^\/*)|(\/*$)/g,"") + "/" + chapterImages[i];
    }
  }
  return piclist;
}@Header:{Referer:thisPage}

